import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule, Router } from '@angular/router';
import { FormsModule } from '@angular/forms';
import { ApiService } from '../../../core/services/api.service';
import { AuthService } from '../../../core/services/auth.service';

@Component({
  selector: 'app-register',
  standalone: true,
  imports: [CommonModule, RouterModule, FormsModule],
  template: `
    <div class="auth-page">
      <div class="auth-card">
        <div class="auth-header">
          <h1>Tạo tài khoản</h1>
          <p>Đăng ký để trải nghiệm đầy đủ tính năng</p>
        </div>
        <form (ngSubmit)="onSubmit()">
          <div class="form-group">
            <label>Họ tên</label>
            <input type="text" class="form-control" [(ngModel)]="fullName" name="fullName" required placeholder="Nhập họ tên của bạn">
          </div>
          <div class="form-group">
            <label>Email</label>
            <input type="email" class="form-control" [(ngModel)]="email" name="email" required placeholder="Nhập email">
          </div>
          <div class="form-group">
            <label>Số điện thoại</label>
            <input type="tel" class="form-control" [(ngModel)]="phone" name="phone" placeholder="Nhập số điện thoại (tùy chọn)">
          </div>
          <div class="form-group">
            <label>Mật khẩu</label>
            <input type="password" class="form-control" [(ngModel)]="password" name="password" required placeholder="Tối thiểu 6 ký tự">
          </div>
          <div class="form-group">
            <label>Xác nhận mật khẩu</label>
            <input type="password" class="form-control" [(ngModel)]="confirmPassword" name="confirmPassword" required placeholder="Nhập lại mật khẩu">
          </div>
          <div class="form-error" *ngIf="error">{{ error }}</div>
          <button type="submit" class="btn btn-primary btn-lg" style="width:100%;" [disabled]="loading">
            {{ loading ? 'Đang đăng ký...' : 'Tạo tài khoản' }}
          </button>
        </form>
        <div class="auth-footer">
          <p>Đã có tài khoản? <a routerLink="/auth/login">Đăng nhập ngay</a></p>
        </div>
      </div>
    </div>
  `,
  styles: [`
    .auth-page { min-height: 80vh; display: flex; align-items: center; justify-content: center; background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); padding: 2rem; }
    .auth-card { background: white; border-radius: 16px; padding: 2.5rem; width: 100%; max-width: 440px; box-shadow: 0 20px 60px rgba(0,0,0,0.2); }
    .auth-header { text-align: center; margin-bottom: 2rem; h1 { margin-bottom: 0.25rem; } p { color: var(--gray); margin: 0; } }
    .auth-footer { text-align: center; margin-top: 1.5rem; p { color: var(--gray); margin: 0; } }
  `]
})
export class RegisterComponent {
  fullName = '';
  email = '';
  phone = '';
  password = '';
  confirmPassword = '';
  error = '';
  loading = false;

  constructor(private api: ApiService, private auth: AuthService, private router: Router) {}

  onSubmit() {
    if (!this.fullName || !this.email || !this.password) return;
    if (this.password !== this.confirmPassword) { this.error = 'Mật khẩu không khớp'; return; }
    if (this.password.length < 6) { this.error = 'Mật khẩu phải có ít nhất 6 ký tự'; return; }
    this.loading = true;
    this.error = '';
    this.api.register({ fullName: this.fullName, email: this.email, phone: this.phone, password: this.password }).subscribe({
      next: (res) => {
        this.auth.login(res.token, res.user);
        this.loading = false;
        this.router.navigate(['/']);
      },
      error: (err) => {
        this.error = err.error?.error || 'Đăng ký thất bại';
        this.loading = false;
      }
    });
  }
}
